var DATA = {"pclass": "Dense Ax=b, n<2000", "rec": "LU with partial pivoting (direct)", "alts": "QR:2x cost|Cholesky if SPD:half cost", "n": "5"};
console.log("Problem class: " + DATA.pclass);
console.log("Recommended: " + DATA.rec);
var N = parseInt(DATA.n, 10) || 5;
// build a small SPD system and solve two ways, timing roughly by operation count
var A = [], b = [];
for (var i = 0; i < N; i++) {
  A.push([]); b.push(i + 1);
  for (var j = 0; j < N; j++) A[i].push(i === j ? 4 : (Math.abs(i - j) === 1 ? -1 : 0));
}
function solveDirect() {
  var M = A.map(function (r) { return r.slice(); }), x = b.slice(), ops = 0;
  for (var k = 0; k < N; k++) {
    for (var i = k + 1; i < N; i++) { var f = M[i][k] / M[k][k]; ops++;
      for (var j = k; j < N; j++) { M[i][j] -= f * M[k][j]; ops++; } x[i] -= f * x[k]; ops++; } }
  for (var i = N - 1; i >= 0; i--) { var s = x[i]; for (var j = i + 1; j < N; j++) { s -= M[i][j] * x[j]; ops++; } x[i] = s / M[i][i]; ops++; }
  return { x: x, ops: ops };
}
function solveJacobi() {
  var x = [], ops = 0;
  for (var i = 0; i < N; i++) x.push(0);
  for (var it = 0; it < 200; it++) {
    var v = [];
    for (var i = 0; i < N; i++) { var s = b[i]; for (var j = 0; j < N; j++) if (j !== i) { s -= A[i][j] * x[j]; ops++; } v.push(s / A[i][i]); ops++; }
    x = v;
  }
  return { x: x, ops: ops };
}
var d = solveDirect(), j = solveJacobi();
console.log("  direct (Gaussian elimination): ops=" + d.ops);
console.log("  iterative (Jacobi x200):       ops=" + j.ops);
var pick = d.ops <= j.ops ? "direct" : "iterative";
console.log("RESULT: for N=" + N + ", '" + pick + "' wins on operation count. Recommended solver '" + DATA.rec + "' " + (pick === "direct" && /direct/i.test(DATA.rec) || pick === "iterative" && /iterative|krylov|multigrid/i.test(DATA.rec) ? "agrees" : "is chosen for larger N") + ".");

